-- ############################################################
-- enrich_20261007_greentown_partners_intro_b3.sql
-- Greentown Labs Houston corporate partners: Korean and English company
-- introductions (intro_ko / intro_en), batch 3 of 4, 12 companies.
-- Country and city are filled only when empty, website only when given here.
-- notes are untouched. Data is base64 JSON. Idempotent.

with x as (
  select *
  from jsonb_to_recordset(convert_from(decode('', 'base64'), 'UTF8')::jsonb)
       as t(id uuid, country_code text, city text, website text, intro_ko text, intro_en text)
)
update app.parties p
set intro_ko     = x.intro_ko,
    intro_en     = x.intro_en,
    country_code = coalesce(p.country_code,
                     (select c.code from app.countries c where c.code = x.country_code)),
    city         = coalesce(nullif(p.city, ''), x.city),
    website      = coalesce(x.website, p.website),
    updated_at   = now()
from x
where p.id = x.id
  and p.deleted_at is null
returning p.party_name, p.country_code, p.city, p.website,
          length(p.intro_ko) as ko_len, length(p.intro_en) as en_len;
